// Met en forme le rapport reçu de devops-agent : un embed Discord et
// deux fichiers (Markdown + HTML) archivés dans MinIO.
//
// L'agent ayant déjà diagnostiqué, il n'y a rien à appeler ici : on
// habille et on range.

const rapport = $json.body || $json;

const gravite = rapport.gravite || 'surveillance';
const namespace = rapport.namespace || '—';
const anomalies = rapport.anomalies || [];
const diagnostic = rapport.diagnostic || '_(aucun diagnostic)_';
const verifications = rapport.verifications || [];
const cout = rapport.cout_dollars ?? 0;
const outils = rapport.outils_appeles || [];
const cluster = rapport.cluster || '';

// Couleur de l'embed selon la gravité.
const COULEURS = { critique: 0xe74c3c, grave: 0xf39c12, surveillance: 0x3498db };
const ICONES = { critique: '🔴', grave: '🟠', surveillance: '🔵' };
const couleur = COULEURS[gravite] || 0x95a5a6;

// Titre : une anomalie seule est nommée, plusieurs sont comptées.
const titre = anomalies.length === 1
  ? `${ICONES[gravite] || '⚪'} ${anomalies[0].ressource} ${anomalies[0].nom} — ${anomalies[0].etat}`
  : `${ICONES[gravite] || '⚪'} ${anomalies.length} anomalies liées dans ${namespace}`;

const listeAnomalies = anomalies
  .map(a => `• \`${a.ressource}/${a.nom}\` — ${a.etat}` +
            (a.redemarrages ? ` (${a.redemarrages} redémarrages)` : ''))
  .join('\n') || '—';

// Discord limite un champ d'embed à 1024 caractères : on tronque le
// diagnostic et on renvoie vers le rapport complet.
const extrait = diagnostic.length > 900
  ? diagnostic.slice(0, 900) + '\n\n_(rapport complet : voir le lien du titre)_'
  : diagnostic;

// ── Chemin d'archivage ───────────────────────────────────────────
// Le conteneur n8n tourne en UTC : on force Europe/Paris pour que
// l'arborescence corresponde à l'heure locale.
const maintenant = new Date();
const local = new Intl.DateTimeFormat('fr-FR', {
  timeZone: 'Europe/Paris',
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false
}).formatToParts(maintenant).reduce((a, p) => (a[p.type] = p.value, a), {});
if (local.hour === '24') local.hour = '00';

const horodatage = `${local.year}-${local.month}-${local.day} ${local.hour}:${local.minute}:${local.second}`;

const slug = String(anomalies[0]?.nom || namespace || 'incident')
  .toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

// Un dossier par incident : les deux formats restent groupés et la
// navigation par date reste lisible.
const dossier = `${local.year}/${local.month}/${local.day}/` +
                `${local.hour}h${local.minute}m${local.second}s-${slug}`;
const cleMd = `${dossier}/rapport.md`;
const cleHtml = `${dossier}/rapport.html`;

// ── Rapport Markdown ─────────────────────────────────────────────
const markdown = [
  `# ${titre}`,
  '',
  `- **Cluster :** ${cluster || '—'}`,
  `- **Namespace :** ${namespace}`,
  `- **Gravité :** ${gravite}`,
  `- **Coût du diagnostic :** ${cout} $`,
  `- **Outils appelés :** ${outils.join(', ') || '—'}`,
  '',
  '## Anomalies détectées',
  '',
  listeAnomalies,
  '',
  '## Diagnostic',
  '',
  diagnostic,
  ...(verifications.length
      ? ['', '## Vérification mécanique', '', verifications.map(v => `- ${v}`).join('\n')]
      : []),
  '',
  '---',
  `_Rapport généré le ${horodatage} (Europe/Paris) par devops-agent_`
].join('\n');

// ── Rapport HTML ─────────────────────────────────────────────────
// Servi en text/html, il s'affiche dans le navigateur au lieu d'être
// téléchargé comme le .md.
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const teinte = { critique: '#e74c3c', grave: '#f39c12', surveillance: '#3498db' }[gravite] || '#95a5a6';

// Rendu Markdown minimal : titres, gras, code, blocs, listes.
const mdVersHtml = (md) => {
  const blocs = md.split(/```/);
  return blocs.map((part, i) => {
    if (i % 2 === 1) {
      const contenu = part.replace(/^(bash|sh|yaml|json)\n/, '').replace(/^\n|\n$/g, '');
      return `<pre><code>${esc(contenu)}</code></pre>`;
    }
    return esc(part)
      .replace(/^### (.+)$/gm, '<h3>$1</h3>')
      .replace(/^## (.+)$/gm, '<h2>$1</h2>')
      .replace(/^# (.+)$/gm, '<h1>$1</h1>')
      .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
      .replace(/`([^`]+)`/g, '<code>$1</code>')
      .split('\n')
      .map(l => /^[-•*] /.test(l) ? `<li>${l.slice(2)}</li>` :
                /^\d+\. /.test(l) ? `<li>${l.replace(/^\d+\. /, '')}</li>` : l)
      .join('\n')
      .replace(/(?:<li>.*<\/li>\n?)+/g, m => `<ul>${m.replace(/\n/g, '')}</ul>`)
      .replace(/\n/g, '<br>')
      .replace(/<br>(<ul>|<\/ul>|<h[123]>)/g, '$1')
      .replace(/(<\/ul>|<\/h[123]>)<br>/g, '$1');
  }).join('');
};

const html = `<!doctype html>
<html lang="fr"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(titre)}</title>
<style>
  :root { color-scheme: light dark; }
  body { margin:0; padding:2rem 1rem; background:#f6f7f9; color:#1a1d21;
         font:15px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif; }
  .wrap { max-width:860px; margin:0 auto; background:#fff; border-radius:10px;
          box-shadow:0 1px 3px rgba(0,0,0,.12); overflow:hidden; }
  header { border-left:5px solid ${teinte}; padding:1.25rem 1.5rem; background:#fafbfc; }
  h1 { margin:0 0 .5rem; font-size:1.35rem; }
  .meta { display:flex; flex-wrap:wrap; gap:.4rem 1.25rem; font-size:.85rem; color:#5b6470; }
  .meta b { color:#1a1d21; font-weight:600; }
  .badge { display:inline-block; padding:.1rem .5rem; border-radius:99px;
           background:${teinte}; color:#fff; font-size:.75rem; font-weight:600; }
  main { padding:1.25rem 1.5rem 2rem; }
  h2 { font-size:1.05rem; margin:1.75rem 0 .5rem; padding-bottom:.3rem;
       border-bottom:1px solid #e6e8eb; }
  h2:first-child { margin-top:0; }
  h3 { font-size:.95rem; margin:1.2rem 0 .3rem; }
  code { background:#eef0f3; padding:.12em .38em; border-radius:4px;
         font:.88em ui-monospace,SFMono-Regular,Menlo,monospace; }
  pre { background:#1e2229; color:#e6e8eb; padding:.9rem 1rem; border-radius:7px;
        overflow-x:auto; }
  pre code { background:none; color:inherit; padding:0; }
  ul { margin:.4rem 0; padding-left:1.3rem; }
  li { margin:.2rem 0; }
  footer { padding:1rem 1.5rem; border-top:1px solid #e6e8eb; color:#8b939e; font-size:.8rem; }
  @media (prefers-color-scheme: dark) {
    body { background:#15181c; color:#e6e8eb; }
    .wrap { background:#1e2229; box-shadow:none; }
    header { background:#22262e; }
    .meta b, h1 { color:#e6e8eb; }
    h2 { border-color:#333a44; }
    code { background:#2b313a; }
    footer { border-color:#333a44; }
  }
</style></head><body><div class="wrap">
<header>
  <h1>${esc(titre)}</h1>
  <div class="meta">
    ${cluster ? `<span><b>Cluster</b> ${esc(cluster)}</span>` : ''}
    <span><b>Namespace</b> ${esc(namespace)}</span>
    <span><b>Gravité</b> <span class="badge">${esc(gravite)}</span></span>
    <span><b>Coût</b> ${cout} $</span>
  </div>
</header>
<main>
  <h2>Anomalies détectées</h2>
  ${mdVersHtml(listeAnomalies)}
  <h2>Diagnostic</h2>
  ${mdVersHtml(diagnostic)}
  ${verifications.length
    ? '<h2>Vérification mécanique</h2>' + mdVersHtml(verifications.map(v => `- ${v}`).join('\n'))
    : ''}
</main>
<footer>Généré le ${horodatage} (Europe/Paris) par devops-agent — <code>${esc(cleMd)}</code></footer>
</div></body></html>`;

// reports.cluster.afflair.app sert le bucket derrière Authelia : le .html
// s'affiche directement, là où la console MinIO ne sait pas le prévisualiser.
const baseRapports = 'https://reports.cluster.afflair.app';
const baseConsole = 'https://minio.cluster.afflair.app/browser/kai-reports';
const encoder = (k) => k.split('/').map(encodeURIComponent).join('/');

const embed = {
  title: titre,
  description: (rapport.resume || '').slice(0, 400),
  color: couleur,
  fields: [
    { name: 'Namespace', value: namespace, inline: true },
    { name: 'Gravité', value: gravite, inline: true },
    { name: 'Coût', value: `${cout} $`, inline: true },
    { name: 'Anomalies', value: listeAnomalies.slice(0, 1024) },
    { name: '🤖 Diagnostic', value: extrait.slice(0, 1024) }
  ],
  timestamp: new Date().toISOString()
};

return [{
  json: {
    embed,
    cleMd,
    cleHtml,
    urlRapport: `${baseRapports}/${encoder(cleHtml)}`,
    urlMarkdown: `${baseConsole}/${encoder(cleMd)}`
  },
  binary: {
    data: {
      data: Buffer.from(markdown, 'utf-8').toString('base64'),
      mimeType: 'text/markdown',
      fileName: 'rapport.md'
    },
    html: {
      data: Buffer.from(html, 'utf-8').toString('base64'),
      mimeType: 'text/html',
      fileName: 'rapport.html'
    }
  }
}];
